def myPow(self, x: float, n: int) -> float:
    def fast_pow(base: float, exp: int) -> float:
        if exp == 0:
            return 1.0
        half = fast_pow(base, exp // 2)
        if exp % 2 == 0:
            return half * half
        return half * half * base

    if n < 0:
        x, n = 1 / x, -n
    return fast_pow(x, n)

