public double myPow(double x, int n) {
    long N = n;
    if (N < 0) {
        x = 1 / x;
        N = -N;
    }
    double result = 1.0;
    double current = x;
    while (N > 0) {
        if ((N & 1) == 1) {
            result *= current;
        }
        current *= current;
        N >>= 1;
    }
    return result;
}

